-- Insert Quiz Questions for Lesson: Read Results and Repeat the Weekly Plan

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 16 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 16 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'read-results-repeat-weekly-plan' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson read-results-repeat-weekly-plan not found in module 16';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Where are available Social Planner results found?', 
    '["CRM → Statistics","Marketing → Social Planner → Statistics","Settings → Analytics","Automation → Reports"]'::jsonb,
    'Marketing → Social Planner → Statistics',
    'Available Social Planner results are found in Marketing → Social Planner → Statistics.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why should similar posts be compared over several weeks?', 
    '["One post can be affected by timing, topic, platform, or chance; several weeks show a more useful pattern","It is required by LeadProspectrr","It reduces the number of posts needed","It automatically improves engagement"]'::jsonb,
    'One post can be affected by timing, topic, platform, or chance; several weeks show a more useful pattern',
    'One post can be affected by timing, topic, platform, or chance. Comparing over several weeks reveals more useful patterns for decision-making.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What are the three posts in the weekly plan?', 
    '["Help, Proof, and Invitation","Image, Video, and Text","Morning, Afternoon, and Evening","Monday, Wednesday, and Friday"]'::jsonb,
    'Help, Proof, and Invitation',
    'The three posts in the weekly plan are Help (answer a question), Proof (share a result), and Invitation (offer a next step).', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
